// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // Adversarial counterparty: deploy a helper that always returns false on transferFrom, simulating a failing call
        FailingToken ft = new FailingToken();
        caddress = address(ft);
        vm.assume(_tos.length > 0);
        bool refOk;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            refOk = true;
        } catch {
            refOk = false;
        }
        // The reference must revert when any call fails (here all calls fail), so refOk is false.
        // The mutant ignores the failure and returns true, so it does not revert.
        assertTrue(!refOk);
    }
}

contract FailingToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }
}

