pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // The deciding factor is whether _tos is empty. Let the fuzzer freely choose any length.
        // No vm.assume restricts the length, so empty arrays are included.
        bool ok;
        try c.transfer(from, caddress, _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Invariant: if _tos is empty, the call must revert.
        // The reference reverts (ok == false), the mutant succeeds (ok == true) when _tos.length == 0.
        assertTrue(_tos.length > 0 || !ok);
    }
}

