pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        Reverter reverter = new Reverter();
        // The fuzzer will sometimes choose caddress == address(reverter)
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: if the external call target is the Reverter, the whole transfer call must revert.
        // The reference reverts for all such inputs; the buggy version succeeds for such an input.
        assertTrue(caddress != address(reverter) || !ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

